import {mapCamera} from './map-camera.050c84d56718.js';import {mapFullscreen} from './map-fullscreen.050c84d56718.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function drawingPanels(entry,lang){return (entry.drawings||[]).map(d=>`<section class="excalidraw-panel" data-drawing="${d.id}"><header><h2>Excalidraw · ${lang==='zh'?'原始画布':'Source drawing'}</h2><p>${esc(d.name.replace(/\.excalidraw$/,''))}</p></header><div class="drawing-controls"><button class="drawing-load">${lang==='zh'?'打开画布':'Open drawing'} (${d.elements})</button><a href="./${d.download}" download="EGDS-${d.id}.excalidraw">${lang==='zh'?'下载 Excalidraw':'Download Excalidraw'} ↗</a></div><div class="drawing-surface"></div><div class="drawing-error" role="status"></div><details class="drawing-references"><summary>${lang==='zh'?'画布中的笔记':'Notes in the drawing'} (${d.references.length})</summary><div>${d.references.map(r=>r.target?`<a href="#/entry/${r.target}">${esc(r.name)} →</a>`:`<span>${esc(r.name)} <small>${lang==='zh'?'未收录':'Not in collection'}</small></span>`).join('')}</div></details><p class="drawing-source">${lang==='zh'?'保留原图布局与历史用词；网页图片使用压缩预览，下载保留原始数据。':'Original layout and historical terminology are preserved. Web images are compressed previews; downloads retain original data.'} ${esc(d.source.path)}</p></section>`).join('');}
export function bindDrawings(entry,lang,{targetId=entry.id}={}){for(const d of entry.drawings||[]){const host=document.querySelector(`[data-drawing="${d.id}"]`);if(!host)continue;const button=host.querySelector('.drawing-load');button.onclick=async()=>{
 const originalLabel=button.textContent;button.disabled=true;button.textContent=lang==='zh'?'正在加载画布…':'Loading drawing…';host.querySelector('.drawing-error').textContent='';
 try{if(!/^drawings\/d-[a-f0-9]+(?:\.[a-f0-9]{12})?\.svg$/.test(d.svg))throw new Error('Invalid drawing path');const response=await fetch('./'+d.svg);if(!response.ok)throw new Error('HTTP '+response.status);let source='';if(response.body){const reader=response.body.getReader(),decoder=new TextDecoder();let bytes=0;while(true){const {value,done}=await reader.read();if(done)break;if(!host.isConnected){await reader.cancel();return;}bytes+=value.length;source+=decoder.decode(value,{stream:true});button.textContent=(lang==='zh'?'正在加载画布 · ':'Loading drawing · ')+(bytes/1048576).toFixed(1)+' MB';}source+=decoder.decode();}else source=await response.text();if(!host.isConnected)return;
 const xml=new DOMParser().parseFromString(source,'image/svg+xml');if(xml.querySelector('parsererror')||xml.documentElement.localName!=='svg')throw new Error('Invalid SVG');
 for(const e of xml.querySelectorAll('script,foreignObject,style,iframe'))e.remove();for(const e of xml.querySelectorAll('*'))for(const a of [...e.attributes]){if(a.name.startsWith('on'))e.removeAttribute(a.name);if(a.localName==='href'&&!/^#|^data:image\/(?:png|jpeg|webp);base64,|^\.\/drawings\/i-[a-f0-9]{16}\.(?:png|webp)$/.test(a.value))e.removeAttribute(a.name);}
 const svg=document.importNode(xml.documentElement,true);svg.classList.add('excalidraw-svg');
 const surface=host.querySelector('.drawing-surface');surface.innerHTML=`<div class="excalidraw-viewport" tabindex="0" aria-label="Excalidraw"><div class="excalidraw-stage"></div></div>`;surface.querySelector('.excalidraw-stage').append(svg);
 const target=svg.querySelector(`a[href="#/entry/${targetId}"]`);const targetBox=target?.getBBox();const canLocate=Boolean(targetBox&&targetBox.width>0&&targetBox.height>0);
 const controls=host.querySelector('.drawing-controls');controls.insertAdjacentHTML('afterbegin',`<button data-drawing-zoom="out" aria-label="${lang==='zh'?'缩小':'Zoom out'}">−</button><output></output><button data-drawing-zoom="in" aria-label="${lang==='zh'?'放大':'Zoom in'}">＋</button><button data-drawing-zoom="fit">${lang==='zh'?'全图':'Fit'}</button>${canLocate?`<button data-drawing-focus>${lang==='zh'?'定位当前词条':'Locate this entry'}</button>`:''}`);button.remove();
 const viewport=surface.querySelector('.excalidraw-viewport'),camera=mapCamera(viewport,svg,{width:d.width,height:d.height,minScale:.01,onZoom:value=>controls.querySelector('output').textContent=Math.round(value*100)+'%'});camera.fit();mapFullscreen(host,controls,{lang,onResize:()=>camera.fit()});
 controls.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.drawingZoom){if(b.dataset.drawingZoom==='fit')camera.fit();else camera.zoomTo(camera.getScale()*(b.dataset.drawingZoom==='in'?1.4:1/1.4));}if(b.hasAttribute('data-drawing-focus')){const link=svg.querySelector(`a[href="#/entry/${targetId}"]`);if(link){const box=link.getBBox();camera.center(box.x+box.width/2,box.y+box.height/2,Math.min(1,viewport.clientWidth/Math.max(600,box.width*2)));}}});
 }catch(error){if(host.isConnected){host.querySelector('.drawing-error').textContent=(lang==='zh'?'画布加载失败，可重试：':'Drawing failed to load. Retry: ')+error.message;button.disabled=false;button.textContent=originalLabel;}}
 };}}
